1	import { redirect } from "next/navigation";
2	import type { Membership } from "@prisma/client";
3	import { currentUser } from "./auth";
4	import { db } from "./db";
5	import { memberCanAccess, type AreaKey } from "./team-areas";
6	
7	/**
8	 * Server-side page guard for org-scoped dashboard pages. Given the active
9	 * organization and the area a page belongs to, it loads the current user's
10	 * membership and redirects home unless the member may reach the area. Returns
11	 * the membership so the page can reuse it.
12	 *
13	 * Lives in its own (server-only) module because it imports ./auth (next/headers);
14	 * the pure area helpers stay in ./team-areas so client components can use them.
15	 */
16	export async function requireArea(orgId: string, area: AreaKey): Promise<Membership> {
17	  const user = await currentUser();
18	  if (!user) redirect("/login");
19	  const membership = await db.membership.findUnique({
20	    where: { orgId_userId: { orgId, userId: user.id } },
21	  });
22	  if (!membership) redirect("/dashboard");
23	  if (!memberCanAccess(membership, area)) redirect("/dashboard");
24	  return membership;
25	}
