204	/** Pure parser exported so the UI can preview before applying. */
205	export async function parseDnsImport(text: string): Promise<ParsedImport> {
206	  const records: RecordInput[] = [];
207	  const errors: string[] = [];
208	  const lines = (text ?? "").split(/\r?\n/);
209	  lines.forEach((line, i) => {
210	    const raw = line.trim();
211	    if (!raw || raw.startsWith("#") || raw.startsWith(";")) return;
212	    // split on comma OR whitespace, but keep the value token intact if quoted
213	    let parts: string[];
214	    if (raw.includes(",")) parts = raw.split(",").map((p) => p.trim());
215	    else parts = raw.split(/\s+/);
216	    if (parts.length < 3) {
217	      errors.push(`Line ${i + 1}: expected at least name, type, value`);
218	      return;
219	    }
220	    const [nameTok, typeTok, valueTok, ttlTok, prioTok] = parts;
221	    const type = typeTok.toUpperCase();
222	    if (!(RECORD_TYPES as readonly string[]).includes(type)) {
223	      errors.push(`Line ${i + 1}: unsupported type "${typeTok}"`);
224	      return;
225	    }
226	    const value = valueTok.replace(/^"|"$/g, "");
227	    const rec: RecordInput = { host: normHost(nameTok), type, answer: value };
228	    if (ttlTok && /^\d+$/.test(ttlTok)) rec.ttl = Math.min(86400, Math.max(60, Number(ttlTok)));
229	    if (type === "MX" && prioTok && /^\d+$/.test(prioTok)) rec.priority = Number(prioTok);
230	    records.push(rec);
231	  });
232	  return { records, errors };
233	}
