68	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
69	    return NextResponse.json({ error: "not found" }, { status: 404 });
70	  }
71	  if (!server.vmid) {
72	    return NextResponse.json({ error: "no VM provisioned" }, { status: 409 });
73	  }
74	  if (server.status !== "RUNNING") {
75	    return NextResponse.json(
76	      { error: "server must be running to open the console" },
77	      { status: 409 }
78	    );
79	  }
80	
81	  // Resolve which Proxmox node + credentials to use. Multi-node servers carry a
82	  // Node row; otherwise fall back to the primary node from the environment.
83	  const apiBase = server.node?.apiUrl ?? process.env.PROXMOX_API_URL ?? "https://127.0.0.1:8006";
84	  const pveNode = server.node?.pveNode ?? primaryNode;
85	  const tokenId = server.node?.tokenId ?? process.env.PROXMOX_TOKEN_ID ?? "";
86	  const tokenSecret = server.node?.tokenSecret ?? process.env.PROXMOX_TOKEN_SECRET ?? "";
87	
88	  if (!pveNode || !tokenId || !tokenSecret) {
89	    return NextResponse.json({ error: "console not configured" }, { status: 500 });
90	  }
91	
92	  // Request a websocket VNC proxy ticket from Proxmox.
93	  let vnc: { ticket: string; port: string | number };
94	  try {
95	    // Use the node-scoped client for non-primary nodes so the ticket is valid
96	    // for the right host; the primary node uses the shared `pve` client.
97	    if (server.node) {
98	      const { pveFor } = await import("@/lib/proxmox");
99	      const client = pveFor({
100	        apiUrl: server.node.apiUrl,
101	        pveNode: server.node.pveNode,
102	        tokenId: server.node.tokenId,
103	        tokenSecret: server.node.tokenSecret,
104	      });
105	      vnc = await client.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
106	        websocket: 1,
107	      });
108	    } else {
109	      vnc = await pve.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
110	        websocket: 1,
111	      });
112	    }
113	  } catch {
114	    return NextResponse.json(
115	      { error: "hypervisor did not grant a console ticket — try again shortly" },
116	      { status: 502 }
117	    );
118	  }
119	
120	  if (!vnc?.ticket || vnc.port === undefined) {
121	    return NextResponse.json({ error: "invalid console ticket from hypervisor" }, { status: 502 });
122	  }
123	
124	  const ticketId = randomUUID();
125	
126	  // Encrypt the full connection target. Only the relay can read this.
127	  const sid = await new EncryptJWT({
128	    apiBase,
129	    node: pveNode,
130	    vmid: server.vmid,
131	    port: Number(vnc.port),
132	    vncticket: vnc.ticket,
133	    tokenId,
134	    tokenSecret,
135	  })
136	    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
137	    .setJti(ticketId)
138	    .setIssuedAt()
139	    .setExpirationTime("60s")
140	    .encrypt(consoleKey());
141	
142	  // Public websocket URL of the relay. In production behind HTTPS, set
143	  // CONSOLE_PUBLIC_WS_URL to a wss:// endpoint (e.g. proxied by nginx) so the
144	  // browser isn't blocked by mixed-content. Otherwise we hand out a bare
145	  // ws://PUBLIC_IP:PORT/console URL for the standalone relay.
146	  const base =
147	    process.env.CONSOLE_PUBLIC_WS_URL?.replace(/\/+$/, "") ??
148	    `ws://${process.env.PUBLIC_IP ?? "127.0.0.1"}:${process.env.CONSOLE_PROXY_PORT ?? "8899"}/console`;
149	
150	  const wsPath = `${base}?sid=${encodeURIComponent(sid)}`;
151	
152	  return NextResponse.json({ wsPath, ticketId });
153	}
