148	  }
149	
150	  let target: string;
151	  try {
152	    const name = validateName((file.name || "upload").trim());
153	    target = joinPath(dir, name);
154	  } catch (err) {
155	    return NextResponse.json(
156	      { error: err instanceof Error ? err.message : "invalid filename" },
157	      { status: 400 }
158	    );
159	  }
160	
161	  try {
162	    const data = Buffer.from(await file.arrayBuffer());
163	    // Re-check the actual byte length in case the reported size was understated.
164	    if (data.length > MAX_UPLOAD_BYTES) {
