7	/**
8	 * Web-terminal authorization ticket issuer.
9	 *
10	 *   POST /api/terminal/token   { serverId }
11	 *
12	 * Flow:
13	 *  1. Authenticate the caller (reuses lib/auth `requireUser`).
14	 *  2. Verify the caller OWNS the target server (userId match — or an admin) and
15	 *     that it is RUNNING. This is the ONLY place the session cookie is checked;
16	 *     the websocket itself is authorized purely by the token minted here.
17	 *  3. Mint a 60-second encrypted token encoding { userId, serverId } and return
18	 *     it. The browser hands this token to the terminal websocket, which
19	 *     re-verifies it and re-checks ownership before SSHing to the VM.
20	 *
21	 * The token is short-lived and single-purpose: it authorizes opening ONE shell
22	 * on ONE server for the user it names. It carries no credentials — the VM's
23	 * root password never leaves the server side.
24	 */
25	export const dynamic = "force-dynamic";
26	
27	export async function POST(req: NextRequest) {
28	  let user;
29	  try {
30	    user = await requireUser();
31	  } catch {
32	    return NextResponse.json({ error: "unauthorized" }, { status: 401 });
33	  }
34	
35	  // Throttle minting per user so a stolen session can't spin up shells in a loop.
36	  const rl = checkRateLimit(`terminal:token:${user.id}`, { max: 20, windowMs: 60_000 });
37	  if (!rl.ok) {
38	    return NextResponse.json(
39	      { error: "too many terminal requests — slow down", retryAfterSec: rl.retryAfterSec },
40	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
41	    );
42	  }
43	
44	  let serverId: unknown;
45	  try {
46	    const body = await req.json();
47	    serverId = body?.serverId;
48	  } catch {
49	    return NextResponse.json({ error: "expected a JSON body" }, { status: 400 });
50	  }
51	  if (typeof serverId !== "string" || !serverId) {
52	    return NextResponse.json({ error: "serverId is required" }, { status: 400 });
53	  }
54	
55	  // Ownership check — same pattern as lib/actions-server-ops.ts / app/api/files:
56	  // the server must exist and belong to the caller (admins may open any).
57	  const server = await db.server.findUnique({
58	    where: { id: serverId },
59	    select: { id: true, userId: true, status: true },
60	  });
61	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
62	    return NextResponse.json({ error: "not found" }, { status: 404 });
63	  }
64	  if (server.status !== "RUNNING") {
65	    return NextResponse.json(
66	      { error: "server must be running to open a terminal" },
67	      { status: 409 }
68	    );
69	  }
70	
71	  const token = await signTerminalToken({ userId: user.id, serverId: server.id });
72	  return NextResponse.json({ token });
