28	    where: { id },
29	    select: { mime: true, data: true },
30	  });
31	  if (!image) return new Response("Not found", { status: 404 });
32	
33	  // Defense in depth: never serve anything that isn't an allow-listed image.
34	  const mime = isAllowedImageMime(image.mime) ? image.mime : "application/octet-stream";
35	
36	  const data: Buffer = Buffer.isBuffer(image.data)
37	    ? image.data
38	    : Buffer.from(image.data as Uint8Array);
