40	  return new Response(new Uint8Array(data), {
41	    status: 200,
42	    headers: {
43	      "Content-Type": mime,
44	      "Content-Length": String(data.length),
45	      "Content-Disposition": 'inline; filename="image"',
46	      "X-Content-Type-Options": "nosniff",
47	      "Content-Security-Policy": "default-src 'none'; sandbox",
48	      "Cache-Control": "public, max-age=31536000, immutable",
