14	// Receives client-side error reports from the error boundaries. Payload is
15	// size-capped and never trusted beyond logging.
16	export async function POST(req: Request) {
17	  // Unauthenticated endpoint: throttle per-IP so it can't be used to amplify
18	  // the ops webhook or pin request slots. Silently no-op when over the limit.
19	  const ip = clientIp(req);
20	  const rl = checkRateLimit(`log:${ip}`, { max: 20, windowMs: 60_000 });
21	  if (!rl.ok) {
22	    return new NextResponse(null, { status: 204 });
23	  }
24	
25	  try {
26	    const body = (await req.json().catch(() => ({}))) as {
27	      context?: string;
28	      message?: string;
29	      digest?: string;
30	      path?: string;
31	      stack?: string;
32	    };
33	    const clip = (s: unknown, n: number) => (typeof s === "string" ? s.slice(0, n) : undefined);
34	    // Fire-and-forget: the webhook fan-out in lib/log.ts awaits an outbound
35	    // fetch, so do NOT block the response on it. Errors are swallowed there.
36	    void logError(clip(body.context, 80) ?? "client-error", { message: clip(body.message, 500), digest: clip(body.digest, 80) }, {
37	      path: clip(body.path, 200),
38	      stack: clip(body.stack, 2000),
39	      source: "client",
40	    });
41	  } catch {
42	    // ignore malformed reports
43	  }
44	  return NextResponse.json({ ok: true });
45	}
