1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { checkRateLimit } from "@/lib/rate-limit";
4	
5	export const runtime = "nodejs";
6	
7	/**
8	 * Page-view capture endpoint. Called fire-and-forget by <VisitTracker/> mounted
9	 * in the marketing layout and the portal Shell. It records a single `Visit` row
10	 * and MUST NOT throw or block the caller — analytics is strictly best-effort.
11	 *
12	 * The client IP is taken only from `x-forwarded-for` (nginx sets it); we never
13	 * trust a body-supplied IP. Bots are dropped by a coarse UA check. The visit
14	 * "kind" (marketing vs portal) comes from a `?k=` query param the mounter sets.
15	 */
16	
17	const BOT_RE =
18	  /bot|crawl|spider|slurp|bingpreview|mediapartners|adsbot|facebookexternalhit|embedly|quora|pinterest|redditbot|whatsapp|telegrambot|discordbot|slackbot|semrush|ahrefs|mj12|dotbot|petalbot|yandex|baidu|duckduckbot|headless|phantomjs|python-requests|python-urllib|go-http|libwww|curl\/|wget\/|okhttp|axios\/|node-fetch|lighthouse|pagespeed|gtmetrix|pingdom|uptimerobot|statuscake|monitor|preview|scrapy/i;
19	
20	/** First hop of x-forwarded-for is the real client (nginx appends downstream). */
21	function clientIp(req: Request): string {
22	  const xff = req.headers.get("x-forwarded-for") ?? "";
23	  const first = xff.split(",")[0]?.trim();
24	  return first || "unknown";
25	}
26	
27	export async function POST(req: Request) {
28	  try {
29	    // Unauthenticated endpoint that writes a durable row per hit — throttle
30	    // per-IP to cap unbounded row insertion. Over the limit: silent no-op.
31	    const rl = checkRateLimit(`track:${clientIp(req)}`, { max: 60, windowMs: 60_000 });
32	    if (!rl.ok) {
33	      return new NextResponse(null, { status: 204 });
34	    }
35	
36	    const url = new URL(req.url);
37	    const kindParam = url.searchParams.get("k");
38	    const kind = kindParam === "portal" ? "portal" : "marketing";
39	
40	    const ua = (req.headers.get("user-agent") ?? "").slice(0, 400);
41	    // Silently accept but skip obvious bots and empty UAs.
42	    if (!ua || BOT_RE.test(ua)) {
43	      return NextResponse.json({ ok: true });
44	    }
45	
46	    const body = (await req.json().catch(() => ({}))) as {
47	      path?: unknown;
48	      referrer?: unknown;
49	    };
50	    const path =
51	      typeof body.path === "string" && body.path ? body.path.slice(0, 300) : "/";
52	    let referrer =
53	      typeof body.referrer === "string" && body.referrer
54	        ? body.referrer.slice(0, 400)
55	        : null;
56	    // Drop same-origin referrers — they're just internal navigation noise.
57	    if (referrer) {
58	      try {
59	        if (new URL(referrer).host === url.host) referrer = null;
60	      } catch {
61	        /* keep opaque referrer strings as-is */
62	      }
63	    }
64	
65	    await db.visit.create({
66	      data: { ip: clientIp(req), path, referrer, ua, kind },
67	    });
68	  } catch {
69	    // Never surface capture failures to the page.
70	  }
71	  return NextResponse.json({ ok: true });
72	}
