2	import { requireUser } from "@/lib/auth";
3	import { checkRateLimit } from "@/lib/rate-limit";
4	import { SANDBOX } from "@/lib/sandbox";
5	import {
6	  cfAuthorizeUrl,
7	  cloudflareOauthConfigured,
8	  packCreds,
9	  pkceChallenge,
10	  randomUrlSafe,
11	} from "@/lib/cloudflare-oauth";
12	import { parseIntent, safeNext, withResult } from "@/lib/cloudflare-connect-intent";
13	import { db } from "@/lib/db";
14	import { runConnectIntent } from "@/lib/cloudflare-intent-run";
15	
16	export const dynamic = "force-dynamic";
17	
18	const base = () => (process.env.APP_URL ?? "").replace(/\/$/, "");
19	
20	/**
21	 * Step 1 of "Connect Cloudflare": start the Authorization Code flow.
22	 *
23	 * Requires a signed-in user, mints a CSRF `state` + PKCE verifier (S256) and
24	 * stashes them — with the intent and the return path — in a short-lived httpOnly
25	 * cookie, then redirects to Cloudflare's consent screen. Nothing sensitive rides
26	 * in the URL; the cookie is the only thing the callback trusts.
27	 */
28	export async function GET(req: NextRequest) {
29	  let user;
30	  try {
31	    user = await requireUser();
32	  } catch {
33	    return NextResponse.redirect(`${base()}/login`);
34	  }
35	
36	  const sp = req.nextUrl.searchParams;
37	  const intent = parseIntent({ intent: sp.get("intent"), id: sp.get("id"), host: sp.get("host") });
38	  const next = safeNext(sp.get("next"));
39	
40	  const rl = checkRateLimit(`cf-oauth-start:${user.id}`, { max: 10, windowMs: 60_000 });
41	  if (!rl.ok) {
42	    return NextResponse.redirect(
43	      `${base()}${withResult(next, { cf: "error", cfmsg: `Too many attempts — try again in ${rl.retryAfterSec}s.` })}`,
44	    );
45	  }
46	
47	  // SANDBOX: never leave the app. Store a synthetic connection and run the
48	  // auto-add straight away so staging exercises the whole "connect → records
49	  // added" path without touching Cloudflare.
50	  if (SANDBOX) {
51	    await db.user.update({
52	      where: { id: user.id },
53	      data: {
54	        cloudflareTokenEnc: packCreds({
55	          accessToken: `sandbox-${randomUrlSafe(12)}`,
56	          refreshToken: `sandbox-${randomUrlSafe(12)}`,
57	          expiresAt: Date.now() + 3600_000,
58	          scope: "sandbox",
59	        }),
60	      },
61	    });
62	    await db.auditLog
63	      .create({ data: { userId: user.id, action: "cloudflare.connect", detail: "OAuth (sandbox)" } })
64	      .catch(() => {});
65	    const outcome = await runConnectIntent(intent);
66	    return NextResponse.redirect(`${base()}${withResult(next, { cf: "connected", ...outcome.params })}`);
67	  }
68	
69	  if (!cloudflareOauthConfigured()) {
70	    return NextResponse.redirect(
71	      `${base()}${withResult(next, {
72	        cf: "error",
73	        cfmsg: "Cloudflare sign-in isn't set up on this server yet — paste an API token instead.",
74	      })}`,
75	    );
76	  }
77	
78	  const state = randomUrlSafe(24);
79	  const verifier = randomUrlSafe(32);
80	  const authUrl = cfAuthorizeUrl({ state, codeChallenge: pkceChallenge(verifier) });
81	
82	  const res = NextResponse.redirect(authUrl);
83	  res.cookies.set({
84	    name: "nx_cf_oauth",
85	    value: JSON.stringify({ state, verifier, next, intent, uid: user.id }),
86	    httpOnly: true,
87	    sameSite: "lax", // must survive the top-level redirect back from Cloudflare
88	    secure: (process.env.APP_URL ?? "").startsWith("https://"),
89	    path: "/api/integrations/cloudflare",
90	    maxAge: 600, // 10 minutes to complete consent
91	  });
92	  return res;
93	}
