1	import { NextRequest, NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { checkRateLimit } from "@/lib/rate-limit";
4	import { checkDomains, registrarConfigured } from "@/lib/registrar";
5	
6	/** First hop of x-forwarded-for is the real client (nginx appends downstream). */
7	function clientIp(req: NextRequest): string {
8	  const xff = req.headers.get("x-forwarded-for") ?? "";
9	  const first = xff.split(",")[0]?.trim();
10	  return first || "unknown";
11	}
12	
13	export async function GET(req: NextRequest) {
14	  const user = await currentUser();
15	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
16	
17	  // Each call fans out to the registrar API — throttle per-IP so a customer
18	  // can't hammer the upstream registrar / rack up lookups.
19	  const rl = checkRateLimit(`domcheck:${clientIp(req)}`, { max: 30, windowMs: 60_000 });
20	  if (!rl.ok) {
21	    return NextResponse.json(
22	      { error: "rate limited", retryAfterSec: rl.retryAfterSec, results: [] },
23	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
24	    );
25	  }
26	
27	  const q = (req.nextUrl.searchParams.get("q") ?? "").toLowerCase().trim().replace(/[^a-z0-9.-]/g, "");
28	  if (q.length < 2) return NextResponse.json({ results: [] });
29	  if (!registrarConfigured()) {
30	    return NextResponse.json({ configured: false, results: [] });
31	  }
32	
33	  const base = q.includes(".") ? q.slice(0, q.indexOf(".")) : q;
34	  const candidates = q.includes(".")
35	    ? [q, ...["com", "net", "io", "dev"].filter((t) => q !== `${base}.${t}`).map((t) => `${base}.${t}`)]
36	    : ["com", "net", "io", "dev", "app", "xyz"].map((t) => `${base}.${t}`);
37	
38	  try {
39	    const checks = await checkDomains(candidates.slice(0, 8));
40	    return NextResponse.json({
41	      configured: true,
42	      results: checks.filter((c) => c.priceCents !== null),
43	    });
44	  } catch (e: any) {
45	    return NextResponse.json({ configured: true, error: String(e?.message ?? e).slice(0, 200), results: [] });
46	  }
47	}
