1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { createHash, randomBytes } from "node:crypto";
5	import bcrypt from "bcryptjs";
6	import { db } from "./db";
7	import { requireUser, realUser } from "./auth";
8	import { generateSecret, otpauthURL, verifyTOTP } from "./totp";
9	import { encryptSecret, decryptSecret } from "./crypto-box";
10	
11	/**
12	 * Resolve a user's TOTP secret, preferring the encrypted column and falling back
13	 * to any legacy plaintext value so already-enrolled users keep working.
14	 */
15	function totpSecretOf(user: { totpSecret: string | null; totpSecretEnc: string | null }): string | null {
16	  return decryptSecret(user.totpSecretEnc) ?? user.totpSecret;
17	}
18	
19	/**
20	 * Two-factor authentication (TOTP) server actions.
21	 *
22	 * Enrolment flow:
23	 *   1. `beginTotpEnrollment()` -> generates a secret, stores it (totpEnabled
24	 *      stays false), and returns the otpauth URI + secret for the UI to show.
25	 *   2. `confirmTotpEnrollment(code)` -> user enters a code from their app; on
26	 *      success `totpEnabled` flips true and backup codes are generated.
27	 *   3. `disableTotp(codeOrPassword)` -> requires a valid TOTP/backup code OR
28	 *      the account password.
29	 *
30	 * Backup codes are one-time; only their sha256 hashes are stored.
31	 */
32	
33	function hashCode(code: string): string {
34	  return createHash("sha256").update(code.trim().toLowerCase()).digest("hex");
35	}
36	
37	/** Generate N human-friendly one-time backup codes (plaintext, for display). */
38	function makeBackupCodes(n = 10): string[] {
39	  return Array.from({ length: n }, () => {
40	    const raw = randomBytes(5).toString("hex"); // 10 hex chars
41	    return `${raw.slice(0, 5)}-${raw.slice(5)}`;
42	  });
43	}
44	
45	/**
46	 * Verify a submitted code for a user: passes if it matches TOTP OR consumes a
47	 * valid one-time backup code (which is then removed). Intended to be called by
48	 * the login flow once the password check succeeds.
49	 */
50	export async function verifyTotpForUser(userId: string, code: string): Promise<boolean> {
51	  const user = await db.user.findUnique({ where: { id: userId } });
52	  if (!user || !user.totpEnabled) return false;
53	  const secret = totpSecretOf(user);
54	  if (!secret) return false;
55	
56	  if (verifyTOTP(secret, code)) return true;
57	
58	  // Fall back to consuming a backup code.
59	  const submitted = hashCode(code);
60	  const idx = user.backupCodes.indexOf(submitted);
61	  if (idx === -1) return false;
62	  const remaining = user.backupCodes.filter((_, i) => i !== idx);
63	  await db.user.update({ where: { id: user.id }, data: { backupCodes: remaining } });
64	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_code_used" } });
65	  return true;
66	}
67	
68	/**
69	 * Step 1: create (but do not yet activate) a TOTP secret.
70	 *
71	 * Return shape keeps `secret`/`otpauthUrl` present (empty on refusal) so the
72	 * existing typed caller (`useState<{secret;otpauthUrl}>`) still compiles; an
73	 * optional `error` is populated when enrolment is refused.
74	 */
75	export async function beginTotpEnrollment(): Promise<{ secret: string; otpauthUrl: string; error?: string }> {
76	  const user = await requireUser();
77	
78	  // Block enrolment while impersonating: the real acting account must be the
79	  // same account being enrolled, so an admin can't seed a customer's 2FA.
80	  const real = await realUser();
81	  if (!real || real.id !== user.id) {
82	    return { secret: "", otpauthUrl: "", error: "You can't set up 2FA while impersonating another account." };
83	  }
84	
85	  // Refuse to overwrite an ALREADY-ACTIVE secret — doing so silently disabled
86	  // the user's working 2FA (totpEnabled=false + fresh secret) with no re-auth.
87	  if (user.totpEnabled === true) {
88	    return { secret: "", otpauthUrl: "", error: "Disable your current 2FA first." };
89	  }
90	
91	  const secret = generateSecret();
92	  // Store encrypted at rest; clear any legacy plaintext value for this account.
93	  await db.user.update({
94	    where: { id: user.id },
95	    data: { totpSecretEnc: encryptSecret(secret), totpSecret: null, totpEnabled: false },
96	  });
97	  return { secret, otpauthUrl: otpauthURL(secret, user.email) };
98	}
99	
100	/** Step 2: confirm enrolment with a code; activates 2FA and returns backup codes. */
101	export async function confirmTotpEnrollment(
102	  prev: unknown,
103	  formData: FormData,
104	): Promise<{ error?: string; ok?: boolean; backupCodes?: string[] }> {
105	  const user = await requireUser();
106	  const code = String(formData.get("code") ?? "");
107	  const secret = totpSecretOf(user);
108	  if (!secret) return { error: "Start enrolment first." };
109	  if (!verifyTOTP(secret, code)) return { error: "That code is incorrect. Try again." };
110	
111	  const backupCodes = makeBackupCodes();
112	  await db.user.update({
113	    where: { id: user.id },
114	    data: { totpEnabled: true, backupCodes: backupCodes.map(hashCode) },
115	  });
116	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_enabled" } });
117	  revalidatePath("/dashboard/settings");
118	  return { ok: true, backupCodes };
119	}
120	
121	/** Regenerate backup codes (invalidates any previous ones). Requires a valid TOTP code. */
122	export async function regenerateBackupCodes(
123	  prev: unknown,
124	  formData: FormData,
125	): Promise<{ error?: string; backupCodes?: string[] }> {
126	  const user = await requireUser();
127	  const code = String(formData.get("code") ?? "");
128	  const secret = totpSecretOf(user);
129	  if (!user.totpEnabled || !secret) return { error: "2FA is not enabled." };
130	  if (!verifyTOTP(secret, code)) return { error: "That code is incorrect." };
131	  const backupCodes = makeBackupCodes();
132	  await db.user.update({ where: { id: user.id }, data: { backupCodes: backupCodes.map(hashCode) } });
133	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_regenerated" } });
134	  return { backupCodes };
135	}
136	
137	/** Disable 2FA. Requires a valid TOTP/backup code OR the account password. */
138	export async function disableTotp(
139	  prev: unknown,
140	  formData: FormData,
141	): Promise<{ error?: string; ok?: boolean }> {
142	  const user = await requireUser();
143	  const proof = String(formData.get("proof") ?? "");
144	  if (!user.totpEnabled) return { error: "2FA is not enabled." };
145	
146	  const secret = totpSecretOf(user);
147	  const codeValid =
148	    (secret ? verifyTOTP(secret, proof) : false) ||
149	    (await verifyTotpForUser(user.id, proof));
150	  const passwordValid = proof.length > 0 && (await bcrypt.compare(proof, user.passwordHash));
151	  if (!codeValid && !passwordValid) {
152	    return { error: "Enter a valid authenticator code, backup code, or your password." };
153	  }
154	
155	  await db.user.update({
156	    where: { id: user.id },
157	    data: { totpEnabled: false, totpSecret: null, totpSecretEnc: null, backupCodes: [] },
158	  });
159	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_disabled" } });
160	  revalidatePath("/dashboard/settings");
161	  return { ok: true };
162	}
