75	export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
76	  const parsed = credsSchema
77	    .extend({
78	      name: z.string().min(1).max(100),
79	      password: z
80	        .string()
81	        .min(8, "Password must be at least 8 characters")
82	        .max(200)
83	        .regex(/[a-zA-Z]/, "Password must include a letter")
84	        .regex(/[0-9]/, "Password must include a number"),
85	    })
86	    .safeParse({
87	    email: formData.get("email"),
88	    password: formData.get("password"),
89	    name: formData.get("name"),
90	  });
91	  if (!parsed.success) return { error: "Enter a valid email, name, and password (min 8 chars)." };
92	  const { email, password, name } = parsed.data;
93	
94	  // Throttle signups per email+IP (reuses the login rate-limit helper) to curb
95	  // automated account creation and welcome-credit farming.
96	  const regHdrs = await headers();
97	  const regIp = (regHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
98	  const regRl = checkRateLimit(`register:${email}:${regIp}`, { max: 5, windowMs: 15 * 60 * 1000 });
99	  if (!regRl.ok) return { error: `Too many attempts. Try again in ${regRl.retryAfterSec}s.` };
100	
101	  const existing = await db.user.findUnique({ where: { email } });
102	  if (existing) return { error: "An account with that email already exists." };
103	
104	  // Capture a referral from the `ref` cookie (set by the register page) if the
105	  // code maps to a real user. Self-referral is impossible here (new account).
106	  const jar = await cookies();
107	  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
108	  let referredById: string | null = null;
109	  if (refCode) {
110	    const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
111	    if (referrer) referredById = referrer.id;
112	  }
113	
114	  const referralCode = await uniqueReferralCode();
115	  const user = await db.user.create({
116	    data: {
117	      email,
118	      name,
119	      passwordHash: await bcrypt.hash(password, 12),
120	      referralCode,
121	      referredById,
122	    },
123	  });
124	  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
125	  // Establish the session first so the freshly-created account is the acting user
126	  // when grantSignupCredit runs (its internal guard requires self-attribution).
127	  await createSession(user.id);
128	  // Grant signup free credit (no-op unless SIGNUP_FREE_CREDIT_CENTS > 0).
129	  try {
130	    await grantSignupCredit(user.id);
131	  } catch { /* non-fatal */ }
132	  jar.delete(REF_COOKIE);
133	  try {
134	    const { sendMail, emails } = await import("./mailer");
135	    const tpl = emails.welcome(name);
136	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
137	  } catch { /* email is best-effort */ }
138	  redirect("/dashboard");
139	}
