198	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
199	async function scheduleNode(planRamMB: number) {
200	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
201	  if (nodes.length === 0) return null;
202	  const loads = await Promise.all(
203	    nodes.map(async (n) => {
204	      const agg = await db.server.findMany({
205	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
206	        select: { plan: { select: { ramMB: true } } },
207	      });
208	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
209	      return { node: n, free: n.capacityRamMB - used };
210	    })
211	  );
212	  loads.sort((a, b) => b.free - a.free);
213	  const best = loads[0];
214	  if (best.free < planRamMB) return best.node; // oversell guard handled by capacityCheck; still return best
215	  return best.node;
216	}
