11	/**
12	 * Internal-only guard for the growth credit functions below.
13	 *
14	 * `grantSignupCredit` / `maybeRewardReferral` are exported from this "use server"
15	 * module, so Next.js registers them as callable action endpoints that would
16	 * otherwise let anyone POST a raw `userId` and mint signup/referral credit. Their
17	 * only legitimate callers invoke them internally: the register / topUp /
18	 * orderServer server actions, the order-placement flow, and the Stripe webhook
19	 * route. A direct client POST to an action carries the `next-action` header;
20	 * server-to-server route/webhook calls do not. So: when the invocation arrives
21	 * through the action dispatcher, only allow it when the real signed-in account is
22	 * acting on its OWN userId (an attacker cannot then target another account);
23	 * non-action server contexts (e.g. the Stripe webhook) are allowed through.
24	 */
25	async function assertInternalGrowthCaller(userId: string): Promise<void> {
26	  const h = await headers();
27	  if (!h.has("next-action")) return; // route handler / webhook / internal call
28	  const real = await realUser();
29	  if (!real || real.id !== userId) throw new Error("FORBIDDEN");
30	}
31	import {
32	  describeCoupon,
33	  referralRewardCents,
34	  signupFreeCreditCents,
35	  type CouponApplyResult,
36	} from "./growth";
37	
38	// ---------- Coupons ----------
39	
40	/**
41	 * Compute the extra wallet credit a coupon grants for a top-up of `baseCents`.
42	 * PERCENT -> baseCents * value%; FIXED_CENTS / CREDIT_CENTS -> flat `value` cents.
43	 */
44	function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
45	  switch (coupon.kind) {
46	    case "PERCENT":
47	      return Math.round((baseCents * coupon.value) / 100);
48	    case "FIXED_CENTS":
49	    case "CREDIT_CENTS":
50	      return coupon.value;
51	    default:
52	      return 0;
53	  }
54	}
55	
56	/**
57	 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
58	 * return the bonus that would be credited. Read-only: it never mutates state,
59	 * so it is safe to call both for the live preview (CouponField) and again inside
60	 * `topUp` to compute the real bonus. Enforces active / expiry / scope /
61	 * minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
62	 */
63	export async function applyCouponToTopup(
64	  code: string,
65	  baseCents: number
66	): Promise<CouponApplyResult> {
67	  const user = await requireUser();
68	  // Global kill-switch: when coupons are disabled no code may be redeemed.
69	  // Checked here so both the live preview and the real `topUp` apply are covered.
70	  if (!(await getSettingBool("coupons_enabled", true))) {
71	    return { ok: false, error: "Promo codes are currently disabled." };
72	  }
73	  const normalized = String(code ?? "").trim().toUpperCase();
74	  if (!normalized) return { ok: false, error: "Enter a promo code." };
75	
76	  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
77	  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
78	  if (coupon.scope === "ORDER") {
79	    return { ok: false, error: "This code only applies to server orders." };
80	  }
81	  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
82	    return { ok: false, error: "This code has expired." };
83	  }
84	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
85	    return { ok: false, error: "This code has reached its redemption limit." };
86	  }
87	  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
88	    return {
89	      ok: false,
90	      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
91	    };
92	  }
93	
94	  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
95	  const already = await db.couponRedemption.findUnique({
96	    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
97	  });
98	  if (already) return { ok: false, error: "You’ve already used this code." };
99	
100	  if (coupon.firstTimeOnly) {
101	    // "First-time" = the user has never received a positive wallet credit before.
102	    const priorCredits = await db.walletTransaction.count({
103	      where: { userId: user.id, amountCents: { gt: 0 } },
104	    });
105	    if (priorCredits > 0) {
106	      return { ok: false, error: "This code is for first-time customers only." };
107	    }
108	  }
109	
110	  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
111	  return {
112	    ok: true,
113	    couponId: coupon.id,
114	    code: coupon.code,
115	    bonusCents,
116	    label: describeCoupon(coupon),
117	  };
118	}
119	
120	// ---------- Admin: coupon management ----------
121	
122	const couponSchema = z.object({
123	  code: z
124	    .string()
125	    .trim()
126	    .min(3)
127	    .max(32)
128	    .regex(/^[A-Za-z0-9_-]+$/, "Code: letters, digits, dashes/underscores only."),
129	  kind: z.enum(["PERCENT", "FIXED_CENTS", "CREDIT_CENTS"]),
130	  scope: z.enum(["ANY", "TOPUP", "ORDER"]),
131	  value: z.coerce.number().int().min(1).max(1_000_000),
132	  firstTimeOnly: z.coerce.boolean(),
133	  minAmountCents: z.coerce.number().int().min(0).max(10_000_000).optional(),
134	  maxRedemptions: z.coerce.number().int().min(1).max(1_000_000).optional(),
135	  expiresAt: z.string().optional(),
136	  note: z.string().max(200).optional(),
137	});
