139	export async function adminCreateCoupon(
140	  prev: any,
141	  formData: FormData
142	): Promise<{ error?: string; ok?: boolean }> {
143	  const admin = await requireAdmin();
144	  const rawExpires = String(formData.get("expiresAt") ?? "").trim();
145	  const rawMin = String(formData.get("minAmountCents") ?? "").trim();
146	  const rawMax = String(formData.get("maxRedemptions") ?? "").trim();
147	  const parsed = couponSchema.safeParse({
148	    code: formData.get("code"),
149	    kind: formData.get("kind"),
150	    scope: formData.get("scope"),
151	    value: formData.get("value"),
152	    firstTimeOnly: formData.get("firstTimeOnly") === "on",
153	    minAmountCents: rawMin === "" ? undefined : rawMin,
154	    maxRedemptions: rawMax === "" ? undefined : rawMax,
155	    expiresAt: rawExpires === "" ? undefined : rawExpires,
156	    note: formData.get("note") || undefined,
157	  });
158	  if (!parsed.success) {
159	    return { error: parsed.error.issues[0]?.message ?? "Invalid coupon." };
160	  }
161	  const data = parsed.data;
162	  if (data.kind === "PERCENT" && data.value > 100) {
163	    return { error: "Percent value must be between 1 and 100." };
164	  }
165	  const code = data.code.toUpperCase();
166	
167	  const existing = await db.coupon.findUnique({ where: { code } });
168	  if (existing) return { error: "A coupon with that code already exists." };
169	
170	  let expiresAt: Date | null = null;
171	  if (data.expiresAt) {
172	    const d = new Date(data.expiresAt);
173	    if (Number.isNaN(d.getTime())) return { error: "Invalid expiry date." };
174	    expiresAt = d;
175	  }
176	
177	  await db.coupon.create({
178	    data: {
179	      code,
180	      kind: data.kind,
181	      scope: data.scope,
182	      value: data.value,
183	      firstTimeOnly: data.firstTimeOnly,
184	      minAmountCents: data.minAmountCents ?? null,
185	      maxRedemptions: data.maxRedemptions ?? null,
186	      expiresAt,
187	      note: data.note ?? null,
188	    },
189	  });
190	  await db.auditLog.create({
191	    data: { userId: admin.id, action: "admin.coupon_create", detail: code },
192	  });
193	  revalidatePath("/admin/coupons");
194	  return { ok: true };
195	}
