197	export async function adminToggleCoupon(id: string): Promise<void> {
198	  const admin = await requireAdmin();
199	  const coupon = await db.coupon.findUnique({ where: { id } });
200	  if (!coupon) return;
201	  await db.coupon.update({ where: { id }, data: { active: !coupon.active } });
202	  await db.auditLog.create({
203	    data: {
204	      userId: admin.id,
205	      action: "admin.coupon_toggle",
206	      detail: `${coupon.code} -> ${!coupon.active ? "active" : "inactive"}`,
207	    },
208	  });
209	  revalidatePath("/admin/coupons");
210	}
211	
212	export async function adminDeleteCoupon(id: string): Promise<void> {
213	  const admin = await requireAdmin();
214	  const coupon = await db.coupon.findUnique({ where: { id } });
215	  if (!coupon) return;
216	  await db.coupon.delete({ where: { id } });
217	  await db.auditLog.create({
218	    data: { userId: admin.id, action: "admin.coupon_delete", detail: coupon.code },
219	  });
220	  revalidatePath("/admin/coupons");
221	}
