12	
13	// Anthropic keys look like `sk-ant-api03-...` — a stable, recognizable prefix
14	// followed by an opaque token. We validate shape only (never call the API here).
15	const ANTHROPIC_KEY_RE = /^sk-ant-[A-Za-z0-9_-]{20,}$/;
16	
17	export async function connectAnthropicKey(key: string): Promise<{ error?: string; ok?: boolean }> {
18	  const user = await requireUser();
19	
20	  const clean = (key ?? "").trim();
21	  if (!clean) {
22	    return { error: "Please paste your Anthropic API key." };
23	  }
24	  if (!ANTHROPIC_KEY_RE.test(clean)) {
25	    return { error: 'That doesn’t look like an Anthropic API key — it should start with "sk-ant-".' };
26	  }
27	
28	  await db.user.update({
29	    where: { id: user.id },
30	    data: { anthropicKeyEnc: encryptSecret(clean) },
31	  });
32	
33	  await db.auditLog
34	    .create({ data: { userId: user.id, action: "user.anthropic_key_connect", detail: "connected" } })
35	    .catch(() => {});
36	
37	  // The key is managed in Settings; the planner reads it to decide if it can run.
38	  revalidatePath("/dashboard/settings");
39	  revalidatePath("/dashboard/build");
40	  return { ok: true };
41	}
