110	export async function requestPasswordReset(prev: any, formData: FormData): Promise<{ sent?: boolean }> {
111	  const email = String(formData.get("email") ?? "").trim().toLowerCase();
112	  // Throttle per email+IP (same helper login uses) to curb reset-email flooding
113	  // and enumeration probing. On limit, still report success below (no leak).
114	  const hdrs = await headers();
115	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
116	  const rl = checkRateLimit(`pwreset:${email}:${ip}`, { max: 5, windowMs: 15 * 60 * 1000 });
117	  if (!rl.ok) return { sent: true };
118	  // Always report success (don't leak which emails exist)
119	  const user = await db.user.findUnique({ where: { email } });
120	  if (user) {
121	    const { randomBytes, createHash } = await import("node:crypto");
122	    const token = randomBytes(32).toString("base64url");
123	    const tokenHash = createHash("sha256").update(token).digest("hex");
124	    await db.passwordResetToken.create({
125	      data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
126	    });
127	    const { sendMail, emails } = await import("./mailer");
128	    const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
129	    const tpl = emails.passwordReset(link);
130	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
131	    await db.auditLog.create({ data: { userId: user.id, action: "user.password_reset_request" } });
132	  }
133	  return { sent: true };
