18	const MAX_PROMPT_CHARS = 2000;
19	const MIN_PROMPT_CHARS = 8;
20	// Cap how many builds a user may have in flight, and how many they can start in
21	// a short window, to keep API + SSH usage sane.
22	const MAX_ACTIVE_BUILDS_PER_USER = 3;
23	const RATE_WINDOW_MS = 60_000;
24	const MAX_BUILDS_PER_WINDOW = 5;
25	
26	// Statuses that mean a build is not yet finished (planning, awaiting approval,
27	// queued, or executing) — used for in-flight accounting.
28	const ACTIVE_STATUSES = ["QUEUED", "PLANNING", "AWAITING_APPROVAL", "RUNNING"] as const;
29	
30	export async function submitBuild(
31	  serverId: string,
32	  prompt: string
33	): Promise<{ error?: string; buildId?: string }> {
34	  const user = await requireUser();
35	
36	  // Feature flag: "Build with Claude" can be switched off platform-wide.
37	  if (!(await getSettingBool("feature_claude_builder", true))) {
38	    return { error: "Build with Claude is currently unavailable." };
39	  }
40	
41	  const clean = (prompt ?? "").trim();
42	  if (clean.length < MIN_PROMPT_CHARS) {
43	    return { error: "Please describe what you'd like Claude to build (a sentence or two)." };
44	  }
45	  if (clean.length > MAX_PROMPT_CHARS) {
46	    return { error: `Prompt is too long (max ${MAX_PROMPT_CHARS} characters).` };
47	  }
48	
49	  // BYOK gate: the owner must have an effective key (their own, or a platform fallback).
50	  const owner = await db.user.findUnique({
51	    where: { id: user.id },
52	    select: { anthropicKeyEnc: true },
53	  });
54	  if (!effectiveKeyFor(owner)) {
55	    return { error: "Add your Anthropic API key in Settings to use Build with AI." };
56	  }
57	
58	  // Ownership: the server must belong to this user.
59	  const server = await db.server.findFirst({ where: { id: serverId, userId: user.id } });
60	  if (!server) return { error: "Server not found." };
61	  if (server.status !== "RUNNING") {
62	    return { error: "The server must be running to build on it." };
63	  }
64	  if (!server.ipAddress || !serverRootPassword(server)) {
65	    return { error: "This server isn't reachable yet — try again once it finishes provisioning." };
66	  }
67	
68	  // Rate sanity.
69	  const active = await db.claudeBuild.count({
70	    where: { userId: user.id, status: { in: [...ACTIVE_STATUSES] } },
71	  });
72	  if (active >= MAX_ACTIVE_BUILDS_PER_USER) {
73	    return { error: "You already have builds in progress. Wait for them to finish before starting another." };
74	  }
75	  const recent = await db.claudeBuild.count({
76	    where: { userId: user.id, createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) } },
77	  });
78	  if (recent >= MAX_BUILDS_PER_WINDOW) {
79	    return { error: "Too many builds started just now — please wait a minute and try again." };
80	  }
81	  // One in-flight build per server keeps the SSH session serialized.
82	  const serverBusy = await db.claudeBuild.count({
83	    where: { serverId, status: { in: [...ACTIVE_STATUSES] } },
84	  });
85	  if (serverBusy > 0) {
86	    return { error: "A build is already in progress on this server." };
87	  }
88	
89	  const build = await db.claudeBuild.create({
90	    data: { userId: user.id, serverId, prompt: clean, status: "QUEUED", approved: false },
91	  });
92	
93	  // Enqueue the worker job; the handler reads the build via payload.buildId.
94	  // Because approved=false, the worker will PLAN (not execute).
95	  await db.job.create({
96	    data: { type: "CLAUDE_BUILD", serverId, payload: { buildId: build.id } },
97	  });
98	
99	  await db.auditLog
100	    .create({
101	      data: { userId: user.id, action: "server.claude_build", detail: `${serverId} ${build.id}` },
102	    })
103	    .catch(() => {});
104	
105	  revalidatePath("/dashboard/build");
106	  return { buildId: build.id };
107	}
