113	export async function approveBuild(id: string): Promise<{ error?: string; ok?: boolean }> {
114	  const user = await requireUser();
115	
116	  const build = await db.claudeBuild.findFirst({ where: { id, userId: user.id } });
117	  if (!build) return { error: "Build not found." };
118	  if (build.status !== "AWAITING_APPROVAL") {
119	    return { error: "This build isn't awaiting approval." };
120	  }
121	  if (!build.plan) {
