129	function validateEventInput(input: EventInput): string | null {
130	  if (!input || typeof input !== "object") return "Invalid event.";
131	  if (!input.calendarId?.trim()) return "Choose a calendar.";
132	  if (!input.title?.trim()) return "Add a title.";
133	  if (!isValidISO(input.start)) return "Invalid start time.";
134	  if (!isValidISO(input.end)) return "Invalid end time.";
135	  if (Date.parse(input.end) < Date.parse(input.start)) return "End must be after start.";
136	  return null;
