140	function validateTaskInput(input: TaskInput): string | null {
141	  if (!input || typeof input !== "object") return "Invalid task.";
142	  if (!input.calendarId?.trim()) return "Choose a calendar.";
143	  if (!input.title?.trim()) return "Add a title.";
144	  if (input.due != null && !isValidISO(input.due)) return "Invalid due date.";
145	  if (
146	    input.priority != null &&
147	    (typeof input.priority !== "number" || input.priority < 0 || input.priority > 9)
148	  ) {
